<?php
namespace App\Http\Controllers; use App\Models\{PracticumClass,PracticumRegistration,TestingHistory,TestingRequest,TestingResult,TestingSample}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class LabStaffController extends Controller {
 public function dashboard(Request $r){ $labId=$r->user()->laboratory_id; $requests=TestingRequest::with(['applicant','service.category','samples','result'])->whereHas('service',fn($q)=>$q->where('laboratory_id',$labId))->latest()->get(); $registrations=PracticumRegistration::with(['student','finalClass.course','finalClass.laboratory'])->where('status','approved')->whereHas('finalClass',fn($q)=>$q->where('laboratory_id',$labId))->latest()->get(); $classes=PracticumClass::with(['course','laboratory'])->withCount(['finalRegistrations'=>fn($q)=>$q->where('status','approved')])->where('laboratory_id',$labId)->where('is_active',true)->orderBy('practicum_date')->orderBy('start_time')->get(); return view('tenaga_labor.dashboard',compact('requests','registrations','classes')); }
 public function updatePracticumScore(Request $r, PracticumRegistration $registration){ $registration->loadMissing('finalClass'); abort_unless($registration->status==='approved' && (int) $registration->finalClass?->laboratory_id===(int) $r->user()->laboratory_id,403); $data=$r->validate(['final_score'=>'required|numeric|min:0|max:100']); $registration->update(['final_score'=>$data['final_score'],'score_entered_by'=>$r->user()->id,'score_entered_at'=>now()]); return back()->with('success','Nilai akhir mahasiswa berhasil disimpan.'); }
 public function updatePracticumClass(Request $r, PracticumClass $class){ abort_unless((int) $class->laboratory_id===(int) $r->user()->laboratory_id,403); $data=$r->validate(['enrollment_deadline'=>'nullable|date','module_file'=>'nullable|file|mimes:pdf|max:10240']); $updates=['enrollment_deadline'=>$data['enrollment_deadline']??null]; if($r->hasFile('module_file')){$updates['module_path']=$r->file('module_file')->store('modul-praktikum','public');} $class->update($updates); return back()->with('success','Batas pengisian dan modul kelompok berhasil diperbarui.'); }
 public function exportPracticumGroup(Request $r, PracticumClass $class){ abort_unless((int) $class->laboratory_id===(int) $r->user()->laboratory_id,403); $class->load(['course','laboratory','finalRegistrations'=>fn($q)=>$q->where('status','approved')->with('student')]); $filename='kelompok-'.$class->course->code.'-'.$class->class_name.'.csv'; return response()->streamDownload(function() use($class){$output=fopen('php://output','w'); fwrite($output,"\xEF\xBB\xBF"); fputcsv($output,['Daftar Mahasiswa Kelompok Praktikum']); fputcsv($output,['Praktikum',$class->course->name]); fputcsv($output,['Kelompok',$class->class_name]); fputcsv($output,['Laboratorium',$class->laboratory->name]); fputcsv($output,['Tanggal',$class->practicum_date?->format('d-m-Y')??'-']); fputcsv($output,[]); fputcsv($output,['No','NPM','Nama']); foreach($class->finalRegistrations as $index=>$registration){fputcsv($output,[$index+1,$registration->student->npm,$registration->student->name]);} fclose($output);},$filename,['Content-Type'=>'text/csv; charset=UTF-8']); }
 public function show(Request $r,TestingRequest $testingRequest){ $this->authorizeLab($r,$testingRequest); $testingRequest->load(['applicant','service.category','service.laboratory','samples','histories.updater','result']); return view('tenaga_labor.test-show',compact('testingRequest')); }
 public function receiveSample(Request $r,TestingRequest $testingRequest){ $this->authorizeLab($r,$testingRequest); $d=$r->validate(['name'=>'required|string|max:150','quantity'=>'required|numeric|min:0.01','unit'=>'required|string|max:30','condition'=>'nullable|string|max:100','notes'=>'nullable|string|max:1000']); DB::transaction(function() use($r,$testingRequest,$d){ TestingSample::create($d+['testing_request_id'=>$testingRequest->id,'code'=>'SMP-'.now()->format('ymd').'-'.strtoupper(Str::random(5)),'received_by'=>$r->user()->id,'received_at'=>now()]); $testingRequest->update(['status'=>'sample_received','assigned_lab_staff_id'=>$r->user()->id]); TestingHistory::create(['testing_request_id'=>$testingRequest->id,'status'=>'sample_received','description'=>'Sampel diterima laboratorium.','updated_by'=>$r->user()->id]); }); return back()->with('success','Sampel diterima dan status diperbarui.'); }
 public function start(Request $r,TestingRequest $testingRequest){ $this->authorizeLab($r,$testingRequest); $testingRequest->update(['status'=>'testing','assigned_lab_staff_id'=>$r->user()->id]); TestingHistory::create(['testing_request_id'=>$testingRequest->id,'status'=>'testing','description'=>'Pengujian sedang berlangsung.','updated_by'=>$r->user()->id]); return back()->with('success','Pengujian dimulai.'); }
 public function complete(Request $r,TestingRequest $testingRequest){ $this->authorizeLab($r,$testingRequest); $d=$r->validate(['letter_number'=>'required|string|max:100','result_summary'=>'required|string|max:5000','result_file'=>'nullable|file|mimes:pdf|max:4096']); $path=$r->hasFile('result_file')?$r->file('result_file')->store('hasil-pengujian','public'):null; DB::transaction(function() use($r,$testingRequest,$d,$path){ TestingResult::updateOrCreate(['testing_request_id'=>$testingRequest->id],['letter_number'=>$d['letter_number'],'result_summary'=>$d['result_summary'],'result_file'=>$path,'issued_by'=>$r->user()->id,'issued_at'=>now()]); $testingRequest->update(['status'=>'completed','completed_at'=>now()]); TestingHistory::create(['testing_request_id'=>$testingRequest->id,'status'=>'completed','description'=>'Pengujian selesai dan surat hasil tersedia.','updated_by'=>$r->user()->id]); }); return back()->with('success','Pengujian diselesaikan dan hasil diterbitkan.'); }
 private function authorizeLab(Request $r,TestingRequest $t): void { $t->loadMissing('service'); abort_unless($t->service->laboratory_id===$r->user()->laboratory_id,403); }
}
